const corsFor=origin=>({"Access-Control-Allow-Origin":origin||"https://dns.lynli.me","Access-Control-Allow-Credentials":"true","Access-Control-Allow-Headers":"Content-Type, Authorization","Access-Control-Allow-Methods":"GET, POST, PATCH, DELETE, OPTIONS","Vary":"Origin"});
const json=(data,status=200,origin)=>new Response(JSON.stringify(data),{status,headers:{"Content-Type":"application/json; charset=utf-8",...corsFor(origin)}});
const b64=v=>btoa(String.fromCharCode(...new Uint8Array(v))).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/,"");
const unb64=s=>Uint8Array.from(atob(String(s).replace(/-/g,"+").replace(/_/g,"/")+"===".slice((String(s).length+3)%4)),c=>c.charCodeAt(0));
const hex=v=>Array.from(new Uint8Array(v),x=>x.toString(16).padStart(2,"0")).join("");
const random=(n=32)=>crypto.getRandomValues(new Uint8Array(n));
const enc=new TextEncoder(), dec=new TextDecoder();
async function hashPassword(password,salt){const k=await crypto.subtle.importKey("raw",enc.encode(password),"PBKDF2",false,["deriveBits"]);return b64(await crypto.subtle.deriveBits({name:"PBKDF2",hash:"SHA-256",salt,iterations:210000},k,256))}
async function hashBytes(s){return new Uint8Array(await crypto.subtle.digest("SHA-256",enc.encode(s)))}
async function digest(s){return hex(await hashBytes(s))}
const tokenFrom=req=>{const h=req.headers.get("Authorization")||"";return h.startsWith("Bearer ")?h.slice(7):""};
const cookie=(req,name)=>{const raw=req.headers.get("Cookie")||"";for(const part of raw.split(";")){const i=part.indexOf("=");if(i>0&&part.slice(0,i).trim()===name)return decodeURIComponent(part.slice(i+1).trim())}return ""};
const requestIpPrefix=req=>{const ip=String(req.headers.get("CF-Connecting-IP")||"");if(ip.includes(":"))return ip.split(":").slice(0,3).join(":")+"::/48";if(/^\d{1,3}(\.\d{1,3}){3}$/.test(ip))return ip.split(".").slice(0,3).join(".")+".0/24";return null};
const appOrigin=env=>String(env.APP_ORIGIN||"https://dns.lynli.me").replace(/\/$/,"");
const safeEqual=(a,b)=>{const x=enc.encode(String(a)),y=enc.encode(String(b));if(x.length!==y.length)return false;let n=0;for(let i=0;i<x.length;i++)n|=x[i]^y[i];return n===0};
async function issueSession(env,id,passwordVersion=1){const token=b64(random()),now=new Date(),idle=new Date(now.getTime()+30*60*1000),absolute=new Date(now.getTime()+7*86400000);await env.DB.prepare("INSERT INTO sessions(id,user_id,token_hash,created_at,last_seen_at,idle_expires_at,absolute_expires_at,password_version) VALUES(?,?,?,?,?,?,?,?)").bind(crypto.randomUUID(),id,await hashBytes(token),now.toISOString(),now.toISOString(),idle.toISOString(),absolute.toISOString(),passwordVersion).run();return token}
async function currentUser(req,env){const t=tokenFrom(req);if(!t)return null;return await env.DB.prepare("SELECT u.id,u.email,u.display_name,u.status,s.id AS session_id FROM sessions s JOIN users u ON u.id=s.user_id LEFT JOIN credentials c ON c.user_id=u.id WHERE s.token_hash=? AND s.revoked_at IS NULL AND s.idle_expires_at>? AND s.absolute_expires_at>? AND (c.password_version IS NULL OR s.password_version=c.password_version) AND u.status='active' AND u.email_verified_at IS NOT NULL AND u.deleted_at IS NULL").bind(await hashBytes(t),new Date().toISOString(),new Date().toISOString()).first()}
async function rateLimit(env,dimension,subject,windowMs,limit){const now=Date.now(),start=new Date(Math.floor(now/windowMs)*windowMs).toISOString(),expires=new Date(Math.floor(now/windowMs)*windowMs+windowMs*2).toISOString(),key=await digest(subject);await env.DB.prepare("INSERT INTO rate_limit_buckets(id,dimension,subject_hash,window_start,count,expires_at) VALUES(?,?,?,?,1,?) ON CONFLICT(dimension,subject_hash,window_start) DO UPDATE SET count=count+1").bind(crypto.randomUUID(),dimension,key,start,expires).run();const row=await env.DB.prepare("SELECT count FROM rate_limit_buckets WHERE dimension=? AND subject_hash=? AND window_start=?").bind(dimension,key,start).first();if(Number(row?.count||0)>limit)throw Object.assign(new Error("请求过于频繁，请稍后重试"),{status:429})}
const rfc3986=value=>encodeURIComponent(String(value)).replace(/[!'()*]/g,c=>"%"+c.charCodeAt(0).toString(16).toUpperCase());

const spaceshipRequest=async(env,path,method="GET",body)=>{
 if(!env.SPACESHIP_API_KEY||!env.SPACESHIP_API_SECRET)throw Object.assign(new Error("Spaceship API 尚未配置：请配置 SPACESHIP_API_KEY 与 SPACESHIP_API_SECRET"),{status:503,code:"SPACESHIP_NOT_CONFIGURED"});
 const response=await fetch("https://spaceship.dev/api/v1"+path,{method,headers:{"X-API-Key":env.SPACESHIP_API_KEY,"X-API-Secret":env.SPACESHIP_API_SECRET,"Accept":"application/json","Content-Type":"application/json"},body:body?JSON.stringify(body):undefined});
 const raw=await response.text();let data={};try{data=raw?JSON.parse(raw):{}}catch{data={detail:raw.slice(0,500)}}
 if(!response.ok){const detail=String(data.detail||data.message||data.title||data.error||"Spaceship API 请求失败（HTTP "+response.status+"）");throw Object.assign(new Error(detail),{status:response.status,providerStatus:response.status,providerData:data})}
 return {data,headers:response.headers,status:response.status};
};
const validateTldDomain=value=>{const domain=String(value||"").trim().toLowerCase().replace(/\.$/,"");if(domain.length>253||!/^(?=.{3,253}$)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/.test(domain))throw Object.assign(new Error("请输入完整有效的域名，例如 myname.com"),{status:400});return domain};
const registrarErrorMessage=err=>{const raw=String(err?.message||"注册商拒绝了本次注册请求");if(/insufficient|not enough|low balance|balance|credit|funds|payment method/i.test(raw))return "注册商余额不足，请等待站长充值。注册商返回："+raw;return "下单失败："+raw};
async function sendMail(env,to,subject,html,text){
 if(!env.RESEND_API_KEY||!env.RESEND_FROM_EMAIL)throw Object.assign(new Error("邮件服务尚未配置"),{status:503});
 const response=await fetch("https://api.resend.com/emails",{method:"POST",headers:{"Authorization":"Bearer "+env.RESEND_API_KEY,"Content-Type":"application/json"},body:JSON.stringify({from:env.RESEND_FROM_EMAIL,to:[to],subject,html,text,attachments:[{filename:"domainhub-logo.png",content:"",content_type:"image/png",content_id:"domainhub-logo"}]})});
 const result=await response.json().catch(()=>({}));
 if(!response.ok||result.error)throw Object.assign(new Error(result.message||result.error?.message||"邮件发送失败"),{status:502});
 return result;
}
const mailHtml=(title,body)=>'<!doctype html><html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+'</title></head><body style="margin:0;padding:0;background-color:#f3f4f6;font-family:Arial,\"Microsoft YaHei\",sans-serif;color:#1f2937"><table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="border-collapse:collapse;background-color:#f3f4f6"><tr><td align="center" style="padding:32px 12px"><table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="width:100%;max-width:560px;border-collapse:separate;background-color:#ffffff;border:1px solid #e5e7eb;border-radius:8px"><tr><td align="center" style="padding:30px 28px 12px"><img src="cid:domainhub-logo" width="40" height="40" alt="DomainHub" style="display:block;width:40px;height:40px;border:0;outline:none;text-decoration:none"></td></tr><tr><td align="center" style="padding:8px 28px 0;font-size:22px;line-height:1.4;font-weight:700;color:#111827">'+title+'</td></tr><tr><td align="center" style="padding:14px 28px 8px;font-size:14px;line-height:1.8;color:#4b5563">'+body+'</td></tr><tr><td align="center" style="padding:24px 28px 28px;font-size:12px;line-height:1.6;color:#6b7280">如果这不是你本人的操作，请忽略此邮件。</td></tr><tr><td align="center" style="padding:16px 20px;border-top:1px solid #f1f5f9;font-size:11px;line-height:1.6;color:#9ca3af">© 2026 DomainHub. 请勿回复此邮件。</td></tr></table></td></tr></table></body></html>';
async function sendVerify(env,email,code){const body='请使用以下验证码完成邮箱验证。<br>验证码有效期为 10 分钟。<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="border-collapse:collapse"><tr><td align="center" style="padding:24px 12px 8px"><div style="font-size:34px;line-height:1.3;font-weight:700;letter-spacing:8px;color:#2563eb">'+code+'</div></td></tr></table>';await sendMail(env,email,"DomainHub 邮箱验证码",mailHtml("验证你的邮箱",body),"DomainHub 官方团队\n邮箱验证码："+code+"\n验证码 10 分钟内有效。请勿向任何人透露。")}
async function sendReset(env,email,code){const body='请使用以下验证码重置账户密码。<br>验证码有效期为 10 分钟。<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="border-collapse:collapse"><tr><td align="center" style="padding:24px 12px 8px"><div style="font-size:34px;line-height:1.3;font-weight:700;letter-spacing:8px;color:#2563eb">'+code+'</div></td></tr></table>';await sendMail(env,email,"DomainHub 密码重置验证码",mailHtml("重置账户密码",body),"DomainHub 官方团队\n密码重置验证码："+code+"\n验证码 10 分钟内有效。")}
const otp=()=>String(new DataView(random(4).buffer).getUint32(0)%1000000).padStart(6,"0");
async function oauthKey(env){if(!env.OAUTH_STATE_ENCRYPTION_KEY)throw new Error("GitHub OAuth 尚未配置 OAUTH_STATE_ENCRYPTION_KEY");const key=unb64(env.OAUTH_STATE_ENCRYPTION_KEY);if(key.length!==32)throw new Error("OAUTH_STATE_ENCRYPTION_KEY 必须是 Base64 编码的 32 字节密钥");return crypto.subtle.importKey("raw",key,{name:"AES-GCM"},false,["encrypt","decrypt"])}
async function encryptVerifier(env,value){const iv=random(12),key=await oauthKey(env),cipher=await crypto.subtle.encrypt({name:"AES-GCM",iv},key,enc.encode(value));const out=new Uint8Array(iv.length+cipher.byteLength);out.set(iv);out.set(new Uint8Array(cipher),iv.length);return out}
async function decryptVerifier(env,value){const bytes=new Uint8Array(value),key=await oauthKey(env);return dec.decode(await crypto.subtle.decrypt({name:"AES-GCM",iv:bytes.slice(0,12)},key,bytes.slice(12)))}
async function githubRequest(url,init){const r=await fetch(url,{...init,headers:{"Accept":"application/json","User-Agent":"DomainHub",...(init?.headers||{})}});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.message||"GitHub OAuth 请求失败");return d}
const quotaOf=async(env,id)=>{const r=await env.DB.prepare("SELECT COALESCE(SUM(delta),0) AS quota FROM quota_ledger WHERE user_id=?").bind(id).first();return Math.max(0,Number(r?.quota||0))};
