async function dnshe(env,route,method="GET",body){if(!env.DNSHE_API_TOKEN){const e=new Error("DNSHE_API_TOKEN 未配置");e.status=503;throw e}const [apiRoute,queryString]=route.split("?");const u=new URL(DNSHE_BASE);u.searchParams.set("api_route","/v1"+apiRoute);if(queryString)new URLSearchParams(queryString).forEach((v,k)=>u.searchParams.set(k,v));const r=await fetch(u.toString(),{method,headers:{"Authorization":"Bearer "+env.DNSHE_API_TOKEN,"Accept":"application/json","Content-Type":"application/json"},body:body?JSON.stringify(body):undefined});const data=await r.json().catch(()=>({}));if(!r.ok){const e=new Error(data?.error?.message||data?.message||"DNSHE 请求失败："+r.status);e.status=r.status>=500?502:r.status;throw e}return data}
